insert into public.artigos_penais (codigo, ordem, titulo, artigo, lei, caput, pena, fonte, observacao, ativo) values
  ('L10826_14', 1, 'Porte ilegal de arma de fogo de uso permitido', 'Art. 14', 'Lei nº 10.826/2003 (Estatuto do Desarmamento)', 'Portar, deter, adquirir, fornecer, receber, ter em depósito, transportar, ceder, ainda que gratuitamente, emprestar, remeter, empregar, manter sob guarda ou ocultar arma de fogo, acessório ou munição, de uso permitido, sem autorização e em desacordo com determinação legal ou regulamentar', 'reclusão, de 2 (dois) a 4 (quatro) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/leis/2003/l10.826compilado.htm', 'Arma de uso restrito é o Art. 16 da mesma lei, que não está no catálogo.', true),
  ('L10826_15', 2, 'Disparo de arma de fogo', 'Art. 15', 'Lei nº 10.826/2003 (Estatuto do Desarmamento)', 'Disparar arma de fogo ou acionar munição em lugar habitado ou em suas adjacências, em via pública ou em direção a ela, desde que essa conduta não tenha como finalidade a prática de outro crime', 'reclusão, de 2 (dois) a 4 (quatro) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/leis/2003/l10.826compilado.htm', '', true),
  ('L11343_33', 3, 'Tráfico de drogas', 'Art. 33', 'Lei nº 11.343/2006 (Lei de Drogas)', 'Importar, exportar, remeter, preparar, produzir, fabricar, adquirir, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, guardar, prescrever, ministrar, entregar a consumo ou fornecer drogas, ainda que gratuitamente, sem autorização ou em desacordo com determinação legal ou regulamentar', 'reclusão de 5 (cinco) a 15 (quinze) anos e pagamento de 500 (quinhentos) a 1.500 (mil e quinhentos) dias-multa', 'https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11343.htm', '', true),
  ('CP_311', 4, 'Adulteração de sinal identificador de veículo (placa)', 'Art. 311', 'Código Penal', 'Adulterar, remarcar ou suprimir número de chassi, monobloco, motor, placa de identificação, ou qualquer sinal identificador de veículo automotor, elétrico, híbrido, de reboque, de semirreboque ou de suas combinações, bem como de seus componentes ou equipamentos, sem autorização do órgão competente', 'reclusão, de três a seis anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_298', 5, 'Falsificação de documento particular', 'Art. 298', 'Código Penal', 'Falsificar, no todo ou em parte, documento particular ou alterar documento particular verdadeiro', 'reclusão, de um a cinco anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Documento público é o Art. 297, que não está no catálogo.', true),
  ('CP_299', 6, 'Falsidade ideológica', 'Art. 299', 'Código Penal', 'Omitir, em documento público ou particular, declaração que dele devia constar, ou nele inserir ou fazer inserir declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante', 'reclusão, de um a cinco anos, e multa, se o documento é público, e reclusão de um a três anos, e multa, se o documento é particular', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_288', 7, 'Associação criminosa', 'Art. 288', 'Código Penal', 'Associarem-se 3 (três) ou mais pessoas, para o fim específico de cometer crimes', 'reclusão, de 1 (um) a 3 (três) anos', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_272', 8, 'Falsificação, corrupção, adulteração ou alteração de produto alimentício', 'Art. 272', 'Código Penal', 'Corromper, adulterar, falsificar ou alterar substância ou produto alimentício destinado a consumo, tornando-o nociva à saúde ou reduzindo-lhe o valor nutritivo', 'reclusão, de 4 (quatro) a 8 (oito) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Confirmar se este crime acontece na operação ferroviária (ex.: carga de grãos adulterada).', true),
  ('CP_260', 9, 'Perigo de desastre ferroviário', 'Art. 260', 'Código Penal', 'Impedir ou perturbar serviço de estrada de ferro: I - destruindo, danificando ou desarranjando, total ou parcialmente, linha férrea, material rodante ou de tração, obra-de-arte ou instalação; II - colocando obstáculo na linha; III - transmitindo falso aviso acerca do movimento dos veículos ou interrompendo ou embaraçando o funcionamento de telégrafo, telefone ou radiotelegrafia; IV - praticando outro ato de que possa resultar desastre', 'reclusão, de dois a cinco anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_250', 10, 'Incêndio', 'Art. 250', 'Código Penal', 'Causar incêndio, expondo a perigo a vida, a integridade física ou o patrimônio de outrem', 'reclusão, de três a seis anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_180', 11, 'Receptação', 'Art. 180', 'Código Penal', 'Adquirir, receber, transportar, conduzir ou ocultar, em proveito próprio ou alheio, coisa que sabe ser produto de crime, ou influir para que terceiro, de boa-fé, a adquira, receba ou oculte', 'reclusão, de 2 (dois) a 6 (seis) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Pena alterada pela Lei nº 15.397/2026 (a planilha tinha 1 a 4 anos).', true),
  ('CP_171', 12, 'Estelionato', 'Art. 171', 'Código Penal', 'Obter, para si ou para outrem, vantagem ilícita, em prejuízo alheio, induzindo ou mantendo alguém em erro, mediante artifício, ardil, ou qualquer outro meio fraudulento', 'reclusão, de 1 (um) a 5 (cinco) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Redação da pena atualizada pela Lei nº 15.397/2026.', true),
  ('CP_168', 13, 'Apropriação indébita', 'Art. 168', 'Código Penal', 'Apropriar-se de coisa alheia móvel, de que tem a posse ou a detenção', 'reclusão, de um a quatro anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_166', 14, 'Alteração de local especialmente protegido', 'Art. 166', 'Código Penal', 'Alterar, sem licença da autoridade competente, o aspecto de local especialmente protegido por lei', 'detenção, de um mês a um ano, ou multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'O título "Crime Ambiental" não corresponde ao Art. 166 do CP. Se a ideia era crime ambiental em geral (queimada, descarte), o certo seria a Lei nº 9.605/1998.', true),
  ('CP_164', 15, 'Introdução ou abandono de animais em propriedade alheia', 'Art. 164', 'Código Penal', 'Introduzir ou deixar animais em propriedade alheia, sem consentimento de quem de direito, desde que o fato resulte prejuízo', 'detenção, de quinze dias a seis meses, ou multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Animal solto na faixa de domínio se encaixa aqui. Maus-tratos é o Art. 32 da Lei nº 9.605/1998.', true),
  ('CP_163', 16, 'Dano', 'Art. 163', 'Código Penal', 'Destruir, inutilizar ou deteriorar coisa alheia', 'detenção, de um a seis meses, ou multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Dano a patrimônio de concessionária de serviço público é dano qualificado (parágrafo único, III).', true),
  ('CP_159', 17, 'Extorsão mediante sequestro', 'Art. 159', 'Código Penal', 'Sequestrar pessoa com o fim de obter, para si ou para outrem, qualquer vantagem, como condição ou preço do resgate', 'reclusão, de oito a quinze anos', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_158', 18, 'Extorsão', 'Art. 158', 'Código Penal', 'Constranger alguém, mediante violência ou grave ameaça, e com o intuito de obter para si ou para outrem indevida vantagem econômica, a fazer, tolerar que se faça ou deixar de fazer alguma coisa', 'reclusão, de quatro a dez anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_157', 19, 'Roubo', 'Art. 157', 'Código Penal', 'Subtrair coisa móvel alheia, para si ou para outrem, mediante grave ameaça ou violência a pessoa, ou depois de havê-la, por qualquer meio, reduzido à impossibilidade de resistência', 'reclusão, de 6 (seis) a 10 (dez) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Pena alterada pela Lei nº 15.397/2026 (a planilha tinha 4 a 10 anos).', true),
  ('CP_155', 20, 'Furto', 'Art. 155', 'Código Penal', 'Subtrair, para si ou para outrem, coisa alheia móvel', 'reclusão, de 1 (um) a 6 (seis) anos, e multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'Pena alterada pela Lei nº 15.397/2026 (a planilha tinha 1 a 4 anos).', true),
  ('CP_150', 21, 'Violação de domicílio', 'Art. 150', 'Código Penal', 'Entrar ou permanecer, clandestina ou astuciosamente, ou contra a vontade expressa ou tácita de quem de direito, em casa alheia ou em suas dependências', 'detenção, de um a três meses, ou multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'O Art. 150 trata de "casa" e suas dependências. Invasão da faixa de domínio ou de pátio talvez não se encaixe; confirmar com o jurídico (esbulho possessório é o Art. 161, II).', true),
  ('CP_148', 22, 'Sequestro e cárcere privado', 'Art. 148', 'Código Penal', 'Privar alguém de sua liberdade, mediante sequestro ou cárcere privado', 'reclusão, de um a três anos', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_147', 23, 'Ameaça', 'Art. 147', 'Código Penal', 'Ameaçar alguém, por palavra, escrito ou gesto, ou qualquer outro meio simbólico, de causar-lhe mal injusto e grave', 'detenção, de um a seis meses, ou multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'A planilha misturava os Arts. 147-A e 147-B; ficou só o 147.', true),
  ('CP_140', 24, 'Injúria', 'Art. 140', 'Código Penal', 'Injuriar alguém, ofendendo-lhe a dignidade ou o decoro', 'detenção, de um a seis meses, ou multa', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_129', 25, 'Lesão corporal', 'Art. 129', 'Código Penal', 'Ofender a integridade corporal ou a saúde de outrem', 'detenção, de três meses a um ano', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', '', true),
  ('CP_121', 26, 'Homicídio', 'Art. 121', 'Código Penal', 'Matar alguém', 'reclusão, de seis a vinte anos', 'https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm', 'A planilha misturava o Art. 122; ficou só o 121 (homicídio simples).', true)
