-- GERADO por tools/gerar_artigos.py a partir de supabase/dados/artigos-penais.json
-- (26 artigos, 26 ativos). Não edite à mão. Precisa da migration 018.

do $$ begin
  if to_regclass('public.artigos_penais') is null then
    raise exception 'Rode antes a migration 018_artigos_penais.sql.';
  end if;
end $$;

begin;
on conflict (codigo) do update set ordem = excluded.ordem, titulo = excluded.titulo, artigo = excluded.artigo,
  lei = excluded.lei, caput = excluded.caput, pena = excluded.pena, fonte = excluded.fonte,
  observacao = excluded.observacao, ativo = excluded.ativo, atualizado_em = now();

-- artigo que saiu da base fica inativo (não é apagado)
update public.artigos_penais set ativo = false, atualizado_em = now()
 where ativo and codigo not in ('L10826_14', 'L10826_15', 'L11343_33', 'CP_311', 'CP_298', 'CP_299', 'CP_288', 'CP_272', 'CP_260', 'CP_250', 'CP_180', 'CP_171', 'CP_168', 'CP_166', 'CP_164', 'CP_163', 'CP_159', 'CP_158', 'CP_157', 'CP_155', 'CP_150', 'CP_148', 'CP_147', 'CP_140', 'CP_129', 'CP_121');
commit;
